defmodule Fides.Origination.Lifecycle.Diagram do
  @moduledoc """
  Renders each country's life cycle as a Mermaid diagram, with what runs on entering
  each state. The code is the source of truth; the generated file is never edited by
  hand.
  """

  alias Fides.Origination.Lifecycle

  @path "priv/generated/life-cycles.md"

  @spec path() :: String.t()
  def path, do: @path

  @spec render() :: String.t()
  def render do
    Enum.join(
      [
        "# Life cycles",
        "Generated by `mix fides.gen.lifecycles` from each country's life cycle. Do not edit by hand.",
        "Every open state can also move to `cancelled`, by the applicant or an analyst. " <>
          "The diagrams leave those moves out so they can be read."
        | Enum.map(Lifecycle.countries(), &render_country/1)
      ],
      "\n\n"
    ) <> "\n"
  end

  defp render_country(country) do
    Enum.join(
      [
        "## #{country}",
        traits(country),
        diagram(country),
        effects(country)
      ],
      "\n\n"
    )
  end

  defp traits(country) do
    bank_data =
      case Lifecycle.bank_data(country) do
        :sync -> "Bank data comes back with the request."
        :async -> "The bank provider delivers the data later, through a signed webhook."
      end

    approval =
      if Lifecycle.countersign?(country),
        do:
          "An analyst's approval above the policy's threshold needs a risk manager's countersignature.",
        else: "An analyst's approval is final."

    bank_data <> " " <> approval
  end

  defp diagram(country) do
    moves =
      for %{to: to} = transition <- Lifecycle.transitions(country), to != :cancelled do
        "  #{transition.from} --> #{to}: #{label(transition)}"
      end

    finals =
      for state <- Lifecycle.states(country),
          state in [:approved, :rejected],
          do: "  #{state} --> [*]"

    Enum.join(
      ["```mermaid", "stateDiagram-v2", "  [*] --> submitted" | moves ++ finals] ++ ["```"],
      "\n"
    )
  end

  defp label(%{actors: actors, guard: guard}) do
    Enum.join(Enum.map(actors, &to_string/1) ++ guard_text(guard), ", ")
  end

  defp guard_text(nil), do: []
  defp guard_text(:within_countersign_threshold), do: ["within the countersign threshold"]
  defp guard_text(:above_countersign_threshold), do: ["above the countersign threshold"]

  defp effects(country) do
    effects = Lifecycle.effects(country)

    rows =
      for state <- Lifecycle.states(country) do
        "| `#{state}` | #{describe(Map.fetch!(effects, state))} |"
      end

    Enum.join(["| On entering | What runs |", "| --- | --- |" | rows], "\n")
  end

  defp describe([]), do: "Nothing"
  defp describe(effects), do: Enum.map_join(effects, "; ", &effect/1)

  defp effect({:transition, to}), do: "The orchestrator moves it to `#{to}`"
  defp effect({:agent, name}), do: "Agent `#{name}`"
  defp effect({:timeout, name}), do: "Timeout `#{name}`"
  defp effect({:retry, name}), do: "Scheduled retry of `#{name}`"
  defp effect({:queue, name}), do: "Enters the `#{name}` queue"
  defp effect({:capability, name}), do: "AI capability `#{name}`"
  defp effect({:webhook, event}), do: "Signed webhook `#{event}`"
  defp effect({:notice, name}), do: "Notice to the applicant, `#{name}`"
  defp effect({:alert, name}), do: "Alert on the console, `#{name}`"
end
